"use client";

import { useEffect, useRef, useState } from "react";
import { Camera, CheckCircle2, XCircle, Loader2 } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";

interface FacePosition {
  type: "front" | "left" | "right";
  label: string;
  instruction: string;
}

interface PointLike {
  x: number;
  y: number;
}

interface LandmarkSet {
  getNose: () => PointLike[];
  getJawOutline: () => PointLike[];
  getLeftEye: () => PointLike[];
  getRightEye: () => PointLike[];
}

const FACE_POSITIONS: FacePosition[] = [
  {
    type: "front",
    label: "Front View",
    instruction: "Look straight at the camera and blink",
  },
  {
    type: "left",
    label: "Left Profile",
    instruction: "Turn your head to the left",
  },
  {
    type: "right",
    label: "Right Profile",
    instruction: "Turn your head to the right",
  },
];

const FRONT_DETECTION_INTERVAL_MS = 120;
const SIDE_DETECTION_INTERVAL_MS = 160;
const CAPTURE_COUNTDOWN_SECONDS = 1;
const FRONT_MIN_FACE_WIDTH_RATIO = 0.16;
const SIDE_MIN_FACE_WIDTH_RATIO = 0.18;
const SIDE_TURN_THRESHOLD = 0.12;

interface AutoCaptureFaceVerificationProps {
  onComplete: (photos: {
    front: Blob;
    left: Blob;
    right: Blob;
  }) => void;
  onCancel?: () => void;
}

export default function AutoCaptureFaceVerification({
  onComplete,
  onCancel,
}: AutoCaptureFaceVerificationProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const streamRef = useRef<MediaStream | null>(null);
  const captureLockRef = useRef(false);
  const isDetectingRef = useRef(false);
  const currentStepRef = useRef(0);
  const faceDetectedStateRef = useRef(false);
  const blinkDetectedRef = useRef(false);
  const errorStateRef = useRef("");
  const blinkArmedRef = useRef(false);
  const blinkStartRef = useRef<number | null>(null);
  const earSamplesRef = useRef<number[]>([]);
  const closedFramesRef = useRef(0);
  const openFramesRef = useRef(0);
  const lastBlinkAtRef = useRef<number | null>(null);
  const prevEarRef = useRef<number | null>(null);
  const lastDropTimeRef = useRef<number | null>(null);
  const detectInFlightRef = useRef(false);
  const sideSeenStreakRef = useRef(0);
  const captureTimeoutRef = useRef<number | null>(null);
  const countdownIntervalRef = useRef<number | null>(null);
  const rafRef = useRef<number | null>(null);
  const lastDetectionAtRef = useRef(0);
  const modelsLoadedRef = useRef(false);
  const faceApiRef = useRef<typeof import("face-api.js") | null>(null);
  const [currentStep, setCurrentStep] = useState(0);
  const [capturedPhotos, setCapturedPhotos] = useState<{
    front?: Blob;
    left?: Blob;
    right?: Blob;
  }>({});
  const [error, setError] = useState<string>("");
  const [faceDetected, setFaceDetected] = useState(false);
  const [blinkDetected, setBlinkDetected] = useState(false);
  const [countdown, setCountdown] = useState<number | null>(null);

  const currentPosition = FACE_POSITIONS[currentStep];

  // Initialize camera
  useEffect(() => {
    startCamera();
    return () => {
      stopCamera();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    currentStepRef.current = currentStep;
    if (currentStep !== 0) {
      // Reset blink detection state when leaving the front-view step
      blinkArmedRef.current = false;
      blinkStartRef.current = null;
      earSamplesRef.current = [];
      closedFramesRef.current = 0;
      openFramesRef.current = 0;
      prevEarRef.current = null;
      lastDropTimeRef.current = null;
    }
  }, [currentStep]);

  useEffect(() => {
    faceDetectedStateRef.current = faceDetected;
  }, [faceDetected]);

  useEffect(() => {
    blinkDetectedRef.current = blinkDetected;
  }, [blinkDetected]);

  useEffect(() => {
    errorStateRef.current = error;
  }, [error]);

  const updateFaceDetected = (next: boolean) => {
    if (faceDetectedStateRef.current !== next) {
      faceDetectedStateRef.current = next;
      setFaceDetected(next);
    }
  };

  const updateBlinkDetected = (next: boolean) => {
    if (blinkDetectedRef.current !== next) {
      blinkDetectedRef.current = next;
      setBlinkDetected(next);
    }
  };

  const updateError = (next: string) => {
    if (errorStateRef.current !== next) {
      errorStateRef.current = next;
      setError(next);
    }
  };

  const clearTimers = () => {
    if (captureTimeoutRef.current !== null) {
      window.clearTimeout(captureTimeoutRef.current);
      captureTimeoutRef.current = null;
    }
    if (countdownIntervalRef.current !== null) {
      window.clearInterval(countdownIntervalRef.current);
      countdownIntervalRef.current = null;
    }
  };

  const startCamera = async () => {
    try {
      stopCamera();
      const mediaStream = await navigator.mediaDevices.getUserMedia({
        video: {
          width: { ideal: 640 },
          height: { ideal: 480 },
          frameRate: { ideal: 24, max: 30 },
          facingMode: "user",
        },
      });

      if (videoRef.current) {
        streamRef.current = mediaStream;
        videoRef.current.srcObject = mediaStream;
        isDetectingRef.current = true;
        await videoRef.current.play().catch(() => undefined);
        await startFaceDetection();
      }
    } catch (err) {
      updateError("Unable to access camera. Please grant camera permissions.");
      console.error("Camera error:", err);
      isDetectingRef.current = false;
    }
  };

  const stopCamera = () => {
    isDetectingRef.current = false;
    clearTimers();
    setCountdown(null);
    blinkArmedRef.current = false;
    blinkStartRef.current = null;
    earSamplesRef.current = [];
    closedFramesRef.current = 0;
    openFramesRef.current = 0;
    detectInFlightRef.current = false;
    lastDetectionAtRef.current = 0;
    prevEarRef.current = null;
    lastDropTimeRef.current = null;
    sideSeenStreakRef.current = 0;
    if (rafRef.current !== null) {
      cancelAnimationFrame(rafRef.current);
      rafRef.current = null;
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach((track) => track.stop());
      streamRef.current = null;
    }
  };

  const startFaceDetection = async () => {
    try {
      if (!modelsLoadedRef.current) {
        const faceapi = await import("face-api.js");
        await Promise.all([
          faceapi.nets.tinyFaceDetector.loadFromUri("/models"),
          faceapi.nets.faceLandmark68Net.loadFromUri("/models"),
        ]);
        modelsLoadedRef.current = true;
        faceApiRef.current = faceapi;
      }
      detectFace();
    } catch (err) {
      console.error("Face detection error:", err);
      updateError("Face detection initialization failed");
      isDetectingRef.current = false;
    }
  };

  const median = (values: number[]) => {
    if (values.length === 0) return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const mid = Math.floor(sorted.length / 2);
    return sorted.length % 2 === 0
      ? (sorted[mid - 1] + sorted[mid]) / 2
      : sorted[mid];
  };

  const percentile = (values: number[], p: number) => {
    if (values.length === 0) return 0;
    const sorted = [...values].sort((a, b) => a - b);
    const idx = Math.min(sorted.length - 1, Math.max(0, Math.floor((p / 100) * (sorted.length - 1))));
    return sorted[idx];
  };

  const averagePoint = (points: PointLike[]) => ({
    x: points.reduce((sum, point) => sum + point.x, 0) / points.length,
    y: points.reduce((sum, point) => sum + point.y, 0) / points.length,
  });

  const getFaceMetrics = (box: { x: number; y: number; width: number; height: number }) => {
    const video = videoRef.current;
    if (!video || !video.videoWidth || !video.videoHeight) {
      return {
        centered: false,
        faceWidthRatio: 0,
      };
    }

    const centerX = box.x + box.width / 2;
    const centerY = box.y + box.height / 2;
    const offsetX = Math.abs(centerX - video.videoWidth / 2) / video.videoWidth;
    const offsetY = Math.abs(centerY - video.videoHeight / 2) / video.videoHeight;
    const faceWidthRatio = box.width / video.videoWidth;

    return {
      centered: offsetX < 0.18 && offsetY < 0.2,
      faceWidthRatio,
    };
  };

  const getHeadTurnScore = (landmarks: LandmarkSet) => {
    const nose = averagePoint(landmarks.getNose().slice(3, 6));
    const jaw = landmarks.getJawOutline();
    const leftJaw = jaw[2];
    const rightJaw = jaw[14];
    const faceWidth = distance(leftJaw, rightJaw) || 1;
    const leftDistance = distance(nose, leftJaw);
    const rightDistance = distance(nose, rightJaw);
    return (leftDistance - rightDistance) / faceWidth;
  };

  const detectFace = async () => {
    const faceapi = faceApiRef.current;
    const video = videoRef.current;
    if (!faceapi || !video || !isDetectingRef.current) return;
    if (detectInFlightRef.current) {
      rafRef.current = requestAnimationFrame(detectFace);
      return;
    }

    if (video.readyState < 2) {
      rafRef.current = requestAnimationFrame(detectFace);
      return;
    }

    const position = FACE_POSITIONS[currentStepRef.current];
    const isFront = position.type === "front";
    const now = performance.now();
    const detectionInterval = isFront
      ? FRONT_DETECTION_INTERVAL_MS
      : SIDE_DETECTION_INTERVAL_MS;

    if (now - lastDetectionAtRef.current < detectionInterval) {
      rafRef.current = requestAnimationFrame(detectFace);
      return;
    }

    detectInFlightRef.current = true;
    lastDetectionAtRef.current = now;

    const tinyFront = new faceapi.TinyFaceDetectorOptions({
      inputSize: 224,
      scoreThreshold: 0.4,
    });
    const tinySide = new faceapi.TinyFaceDetectorOptions({
      inputSize: 320,
      scoreThreshold: 0.2,
    });

    try {
      if (isFront) {
        const detection = await faceapi
          .detectSingleFace(video, tinyFront)
          .withFaceLandmarks();

        if (!detection) {
          updateFaceDetected(false);
          updateError("Center your face inside the oval.");
          return;
        }

        const metrics = getFaceMetrics(detection.detection.box);
        if (!metrics.centered) {
          updateFaceDetected(false);
          updateError("Keep your face centered inside the oval.");
          return;
        }

        if (metrics.faceWidthRatio < FRONT_MIN_FACE_WIDTH_RATIO) {
          updateFaceDetected(false);
          updateError("Move a little closer to the camera.");
          return;
        }

        updateFaceDetected(true);
        updateError("");

        if (!blinkDetectedRef.current) {
          const leftEye = detection.landmarks.getLeftEye();
          const rightEye = detection.landmarks.getRightEye();
          const leftEAR = calculateEyeAspectRatio(leftEye);
          const rightEAR = calculateEyeAspectRatio(rightEye);
          const avgEAR = (leftEAR + rightEAR) / 2;

          const samples = earSamplesRef.current;
          samples.push(avgEAR);
          if (samples.length > 24) samples.shift();

          const baseline = Math.max(percentile(samples, 75), median(samples), avgEAR);
          const closeThreshold = Math.max(baseline * 0.72, 0.16);
          const openThreshold = Math.max(baseline * 0.9, 0.22);
          const sampleReady = samples.length >= 8;
          const blinkNow = Date.now();
          const sharpDrop =
            prevEarRef.current !== null &&
            prevEarRef.current - avgEAR > Math.max(baseline * 0.12, 0.03);

          if (avgEAR <= closeThreshold) {
            closedFramesRef.current += 1;
            openFramesRef.current = 0;
          } else if (avgEAR >= openThreshold) {
            openFramesRef.current += 1;
            closedFramesRef.current = 0;
          }

          if (
            sampleReady &&
            !blinkArmedRef.current &&
            (sharpDrop || closedFramesRef.current >= 2)
          ) {
            blinkArmedRef.current = true;
            blinkStartRef.current = blinkNow;
            lastDropTimeRef.current = blinkNow;
          }

          if (blinkArmedRef.current && avgEAR >= openThreshold) {
            const startedAt = blinkStartRef.current ?? lastDropTimeRef.current ?? blinkNow;
            if (
              blinkNow - startedAt <= 900 &&
              (!lastBlinkAtRef.current || blinkNow - lastBlinkAtRef.current > 700)
            ) {
              lastBlinkAtRef.current = blinkNow;
              updateBlinkDetected(true);
              blinkArmedRef.current = false;
              blinkStartRef.current = null;
              lastDropTimeRef.current = null;
              closedFramesRef.current = 0;
              openFramesRef.current = 0;
              window.setTimeout(() => autoCapture(), 200);
            } else {
              blinkArmedRef.current = false;
              blinkStartRef.current = null;
              lastDropTimeRef.current = null;
            }
          }

          if (
            blinkArmedRef.current &&
            blinkStartRef.current &&
            blinkNow - blinkStartRef.current > 1000
          ) {
            blinkArmedRef.current = false;
            blinkStartRef.current = null;
            lastDropTimeRef.current = null;
            closedFramesRef.current = 0;
            openFramesRef.current = 0;
          }

          prevEarRef.current = avgEAR;
        }
      } else {
        const detection = await faceapi
          .detectSingleFace(video, tinySide)
          .withFaceLandmarks();

        if (!detection) {
          updateFaceDetected(false);
          sideSeenStreakRef.current = 0;
          updateError("Turn your head and keep your face inside the oval.");
          return;
        }

        const metrics = getFaceMetrics(detection.detection.box);
        const headTurnScore = getHeadTurnScore(detection.landmarks);
        const wantsLeft = position.type === "left";
        const turnedEnough = wantsLeft
          ? headTurnScore >= SIDE_TURN_THRESHOLD
          : headTurnScore <= -SIDE_TURN_THRESHOLD;

        if (!metrics.centered) {
          updateFaceDetected(false);
          sideSeenStreakRef.current = 0;
          updateError("Keep your face centered inside the oval.");
          return;
        }

        if (metrics.faceWidthRatio < SIDE_MIN_FACE_WIDTH_RATIO) {
          updateFaceDetected(false);
          sideSeenStreakRef.current = 0;
          updateError("Move a little closer to the camera.");
          return;
        }

        if (!turnedEnough) {
          updateFaceDetected(false);
          sideSeenStreakRef.current = 0;
          updateError(
            wantsLeft
              ? "Turn a bit more to your left."
              : "Turn a bit more to your right."
          );
          return;
        }

        updateFaceDetected(true);
        updateError("");
        sideSeenStreakRef.current = Math.min(sideSeenStreakRef.current + 1, 4);

        if (
          sideSeenStreakRef.current >= 2 &&
          captureTimeoutRef.current === null &&
          !captureLockRef.current
        ) {
          captureTimeoutRef.current = window.setTimeout(() => {
            captureTimeoutRef.current = null;
            if (isDetectingRef.current && !captureLockRef.current) {
              autoCapture();
            }
          }, 350);
        }
      }
    } catch (err) {
      console.error("Face detection loop error:", err);
      updateFaceDetected(false);
      updateError("We couldn't analyze the camera feed. Please try again.");
    } finally {
      detectInFlightRef.current = false;
    }

    if (isDetectingRef.current) {
      rafRef.current = requestAnimationFrame(detectFace);
    }
  };

  const calculateEyeAspectRatio = (eye: PointLike[]) => {
    const vertical1 = distance(eye[1], eye[5]);
    const vertical2 = distance(eye[2], eye[4]);
    const horizontal = distance(eye[0], eye[3]);
    return (vertical1 + vertical2) / (2.0 * horizontal);
  };

  const distance = (p1: PointLike, p2: PointLike) => {
    return Math.sqrt(Math.pow(p2.x - p1.x, 2) + Math.pow(p2.y - p1.y, 2));
  };

  const autoCapture = (countFrom = CAPTURE_COUNTDOWN_SECONDS) => {
    if (!videoRef.current || !canvasRef.current) return;
    if (captureLockRef.current) return;
    captureLockRef.current = true;
    if (captureTimeoutRef.current !== null) {
      window.clearTimeout(captureTimeoutRef.current);
      captureTimeoutRef.current = null;
    }

    setCountdown(countFrom);
    if (countdownIntervalRef.current !== null) {
      window.clearInterval(countdownIntervalRef.current);
      countdownIntervalRef.current = null;
    }
    if (countFrom <= 0) {
      capturePhoto();
      return;
    }
    countdownIntervalRef.current = window.setInterval(() => {
      setCountdown((prev) => {
        if (prev === 1) {
          if (countdownIntervalRef.current !== null) {
            window.clearInterval(countdownIntervalRef.current);
            countdownIntervalRef.current = null;
          }
          capturePhoto();
          return null;
        }
        return prev! - 1;
      });
    }, 1000);
  };

  const capturePhoto = () => {
    if (!videoRef.current || !canvasRef.current) {
      captureLockRef.current = false;
      return;
    }

    const canvas = canvasRef.current;
    const video = videoRef.current;
    
    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    
    const ctx = canvas.getContext("2d");
    if (!ctx) {
      captureLockRef.current = false;
      return;
    }

    ctx.drawImage(video, 0, 0);

    canvas.toBlob((blob) => {
      if (!blob) {
        captureLockRef.current = false;
        return;
      }

      const stepIndex = currentStepRef.current;
      const position = FACE_POSITIONS[stepIndex];
      const newPhotos = {
        ...capturedPhotos,
        [position.type]: blob,
      };
      setCapturedPhotos(newPhotos);

      // Move to next step or complete
      if (stepIndex < FACE_POSITIONS.length - 1) {
        setCurrentStep(stepIndex + 1);
        updateFaceDetected(false);
        updateBlinkDetected(false);
      } else {
        // All photos captured
        isDetectingRef.current = false;
        stopCamera();
        onComplete({
          front: newPhotos.front!,
          left: newPhotos.left!,
          right: newPhotos.right!,
        });
      }
      captureLockRef.current = false;
    }, "image/jpeg", 0.95);
  };

  const retakePhoto = () => {
    const newPhotos = { ...capturedPhotos };
    delete newPhotos[currentPosition.type as keyof typeof capturedPhotos];
    setCapturedPhotos(newPhotos);
    updateFaceDetected(false);
    updateBlinkDetected(false);
    blinkArmedRef.current = false;
    blinkStartRef.current = null;
    earSamplesRef.current = [];
    closedFramesRef.current = 0;
    openFramesRef.current = 0;
    prevEarRef.current = null;
    lastDropTimeRef.current = null;
    setCountdown(null);
    captureLockRef.current = false;
  };

  return (
    <Card className="p-4 max-w-2xl mx-auto">
      <div className="space-y-4">
        {/* Header */}
        <div className="text-center">
          <h2 className="text-xl font-bold mb-1">Face Verification</h2>
          <p className="text-sm text-muted-foreground">
            Step {currentStep + 1} of {FACE_POSITIONS.length}:{" "}
            {currentPosition.label}
          </p>
        </div>

        {/* Progress */}
        <div className="flex gap-2 justify-center">
          {FACE_POSITIONS.map((pos, idx) => (
            <div
              key={pos.type}
              className={`h-1.5 w-16 rounded-full transition-colors ${
                idx < currentStep
                  ? "bg-green-500"
                  : idx === currentStep
                  ? "bg-blue-500"
                  : "bg-gray-200"
              }`}
            />
          ))}
        </div>

        {/* Camera View */}
        <div className="relative h-[240px] sm:h-[280px] bg-black rounded-lg overflow-hidden">
          <video
            ref={videoRef}
            autoPlay
            playsInline
            muted
            className="w-full h-full object-cover mirror"
          />
          
          {/* Face Oval Guide */}
          <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <div
              className={`w-56 h-72 border-4 rounded-full transition-colors ${
                faceDetected ? "border-green-500" : "border-white/50"
              }`}
              style={{
                boxShadow: "0 0 0 9999px rgba(0, 0, 0, 0.5)",
              }}
            />
          </div>

          {/* Countdown */}
          {countdown && (
            <div className="absolute inset-0 flex items-center justify-center bg-black/50">
              <div className="text-white text-8xl font-bold animate-pulse">
                {countdown}
              </div>
            </div>
          )}

          {/* Status Indicators */}
          <div className="absolute top-4 left-4 right-4 space-y-2">
            {faceDetected && (
              <Alert className="bg-green-500/90 text-white border-0">
                <CheckCircle2 className="h-4 w-4" />
                <AlertDescription>Face detected</AlertDescription>
              </Alert>
            )}
            
            {currentPosition.type === "front" && faceDetected && !blinkDetected && (
              <Alert className="bg-blue-500/90 text-white border-0">
                <Loader2 className="h-4 w-4 animate-spin" />
                <AlertDescription>Please blink</AlertDescription>
              </Alert>
            )}
          </div>
        </div>

        <canvas ref={canvasRef} className="hidden" />

        {/* Instructions */}
        <Alert>
          <Camera className="h-4 w-4" />
          <AlertDescription className="text-sm font-medium">
            {currentPosition.instruction}
          </AlertDescription>
        </Alert>

        <p className="text-xs text-muted-foreground">
          If auto-detect feels slow on your camera, you can use the manual capture button below for each angle.
        </p>

        {/* Error */}
        {error && (
          <Alert variant="destructive">
            <XCircle className="h-4 w-4" />
            <AlertDescription>{error}</AlertDescription>
          </Alert>
        )}

        {/* Actions */}
        <div className="flex gap-3">
          <Button
            type="button"
            onClick={() => autoCapture(1)}
            variant="secondary"
            className="flex-1"
            disabled={countdown !== null}
          >
            {currentPosition.type === "front" ? "Capture Front Manually" : "Capture This Angle"}
          </Button>
          {capturedPhotos[currentPosition.type] && (
            <Button onClick={retakePhoto} variant="outline" className="flex-1">
              Retake Photo
            </Button>
          )}
          {onCancel && (
            <Button
              onClick={() => {
                stopCamera();
                onCancel();
              }}
              variant="ghost"
              className="flex-1"
            >
              Cancel
            </Button>
          )}
        </div>

        {/* Captured Photos Preview */}
        <div className="grid grid-cols-3 gap-2">
          {FACE_POSITIONS.map((pos) => (
            <div
              key={pos.type}
              className={`h-16 rounded-lg border-2 flex items-center justify-center ${
                capturedPhotos[pos.type]
                  ? "border-green-500 bg-green-50"
                  : "border-gray-200 bg-gray-50"
              }`}
            >
              {capturedPhotos[pos.type] ? (
                <CheckCircle2 className="h-6 w-6 text-green-500" />
              ) : (
                <span className="text-xs text-muted-foreground">
                  {pos.label}
                </span>
              )}
            </div>
          ))}
        </div>
      </div>

      <style jsx>{`
        .mirror {
          transform: scaleX(-1);
        }
      `}</style>
    </Card>
  );
}
